var Q20=[
{n:1,q:'En el artículo 17 de la Constitución Española de 1978, se dispone...',o:{a:'Que toda persona tiene derecho a su libertad y dignidad.',b:'Que se garantiza la libertad ideológica, religiosa y de culto de los individuos y de las comunidades.',c:'Que la detención preventiva no podrá durar más del tiempo estrictamente necesario para la realización de las averiguaciones tendentes al esclarecimiento de los hechos, y, en todo caso, en el plazo máximo de 24 horas, el detenido deberá ser puesto en libertad o a disposición de la autoridad judicial.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'d',why:{d:'El art. 17 CE dispone que toda persona tiene derecho a la libertad y seguridad (no solo dignidad), y que el plazo máximo de detención es de 72 horas, no 24. Ninguna opción reproduce correctamente el artículo.'}}
,{n:2,q:'En el artículo 17 de la Constitución Española de 1978 se dispone...',o:{a:'Que se garantiza la asistencia de abogado al detenido en las diligencias policiales y judiciales, en los términos que la ley establezca.',b:'Que nadie puede ser privado de su libertad, sino de acuerdo con lo que reglamentariamente se determine.',c:'Que ninguna persona detenida podrá ser obligada a declarar, salvo lo se determine en una norma con rango de ley orgánica para miembros de grupos armados u organizaciones terroristas.',d:'Todas las respuestas anteriores son correctas.'},correct:'a',why:{a:'El art. 17.3 CE dispone que se garantiza la asistencia de abogado al detenido en las diligencias policiales y judiciales, en los términos que la ley establezca.'}}
,{n:3,q:'En el artículo 17 de la Constitución Española de 1978 se dispone...',o:{a:'Que la detención preventiva no podrá durar más del tiempo estrictamente necesario para la realización de las averiguaciones tendentes al esclarecimiento de los hechos, y, en todo caso, en el plazo máximo de 72 horas, el detenido deberá ser puesto en libertad o a disposición de la autoridad judicial.',b:'Que toda persona detenida debe ser informada de forma inmediata, y de modo que le sea comprensible, de sus derechos y de los hechos que se le imputan.',c:'Que toda persona detenida debe ser informada de forma inmediata, y de modo que le sea comprensible, de los hechos que se le imputan.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 17 CE establece el plazo máximo de 72 horas, la información inmediata de derechos y hechos imputados. Todas las afirmaciones son correctas.'}}
,{n:4,q:'En la vigente Ley de Enjuiciamiento Criminal, la detención...',o:{a:'Está regulada en el Capítulo I del Título VI, de su Libro II.',b:'Está regulada en el Capítulo II del Título VII, de su Libro II.',c:'Está regulada en el Capítulo III del Título VI, de su Libro III.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'d',why:{d:'La detención en la LECrim está regulada en el Capítulo II del Título VI, de su Libro II, y ninguna de las opciones a, b o c lo reproduce correctamente.'}}
,{n:5,q:'En la vigente Ley de Enjuiciamiento Criminal, la detención...',o:{a:'Está regulada en el Capítulo II del Título V, de su Libro II.',b:'Está regulada en el Capítulo II del Título VI, de su Libro II.',c:'Está regulada en el Capítulo II del Título VII, de su Libro II.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'b',why:{b:'La detención en la LECrim está regulada en el Capítulo II del Título VI, del Libro II.'}}
,{n:6,q:'En la vigente Ley de Enjuiciamiento Criminal, la detención está regulada en los artículos...',o:{a:'489 a 501.',b:'487 a 503.',c:'489 a 503.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'c',why:{c:'La detención en la LECrim está regulada en los artículos 489 a 503.'}}
,{n:7,q:'En el artículo 489 de la Ley de Enjuiciamiento Criminal se dispone que...',o:{a:'Ningún español, natural o asimilado, podrá ser detenido sino en los casos y en la forma previstos en la Ley.',b:'Ningún español ni extranjero, podrá ser detenido sino en los casos y en la forma que las leyes prescriban.',c:'Ningún español de origen podrá ser detenido sino en los casos y en la forma que las leyes prescriban.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'b',why:{b:'El art. 489 LECrim establece que ningún español ni extranjero podrá ser detenido sino en los casos y en la forma que las leyes prescriban.'}}
,{n:8,q:'Conforme a lo dispuesto en el artículo 490 de la Ley de Enjuiciamiento Criminal, cualquier persona puede detener:',o:{a:'Al que intentare cometer un delito, en el momento de ir a cometerlo.',b:'Al delincuente "in fraganti".',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 490 LECrim establece que cualquier persona puede detener al que intentare cometer un delito en el momento de ir a cometerlo y al delincuente in fraganti.'}}
,{n:9,q:'Conforme a lo dispuesto en el artículo 490 de la Ley de Enjuiciamiento Criminal, cualquier persona puede detener:',o:{a:'Al que se fugare de la cárcel en que estuviere esperando su traslado al establecimiento penal o lugar en que deba cumplir la condena.',b:'Al que estuviere procesado por delito que tenga señalada pena superior a la de prisión correccional.',c:'Al que hubiere cometido una infracción penal o administrativa, siempre que no quede acreditada su identidad por cualquier medio admisible en Derecho.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 490 LECrim establece que cualquier persona puede detener al fugado de la cárcel, al procesado por delito con pena superior a prisión correccional, y al de identidad no acreditada.'}}
,{n:10,q:'Según el artículo 490 de la Ley de Enjuiciamiento Criminal, cualquier persona puede detener:',o:{a:'Al que se fugare estando detenido o preso por causa pendiente.',b:'Al procesado o condenado que estuviere en rebeldía.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'d',why:{d:'El art. 490 LECrim establece que cualquier persona puede detener al fugado estando detenido o preso, y al procesado o condenado en rebeldía.'}}
,{n:11,q:'Según el artículo 492 de la Ley de Enjuiciamiento Criminal, la autoridad o agente de la Policía Judicial tendrán la obligación de detener a quien, no estando todavía procesado, se halle en las circunstancias del artículo 490 de esta Ley, siempre y cuando...',o:{a:'Se trate de un delito "in fraganti".',b:'El reo no tuviese domicilio conocido ni diese fianza bastante a juicio de la autoridad o agente que intente detenerle.',c:'La autoridad o agente tenga motivos racionalmente suficientes para creer en la existencia de un hecho que presente los caracteres de delito y que la persona a quien intente detener tuvo participación en el.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'d',why:{d:'El art. 492 LECrim establece varias condiciones para la detención obligatoria. Ninguna de las opciones reproduce con exactitud el artículo. La obligación surge cuando concurran los supuestos del art. 490 de forma conjunta.'}}
,{n:12,q:'Según el artículo 492.4 de la Ley de Enjuiciamiento Criminal, la autoridad o agente de la Policía Judicial tendrán la obligación de detener a quien, no estando todavía procesado, se halle en las circunstancias del artículo 490.3, siempre y cuando...',o:{a:'Se trate de un delito "in fraganti".',b:'El reo no tuviese domicilio conocido ni diese fianza bastante a juicio de la autoridad o agente que intente detenerle.',c:'La autoridad o agente tenga motivos racionalmente suficientes para creer en la existencia de un hecho que presente los caracteres de delito y que la persona a quien intente detener tuvo participación en el.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'b',why:{b:'El art. 492.4 LECrim establece la obligación de detener a quien se halle en las circunstancias del art. 490.3 cuando el reo no tuviese domicilio conocido ni diese fianza bastante a juicio del agente.'}}
,{n:13,q:'Según el artículo 491 de la Ley de Enjuiciamiento Criminal, el particular que detuviere a otro si este lo exigiere...',o:{a:'Justificará haber obrado en virtud de motivos racionalmente suficientes para creer que el detenido se hallaba comprendido en alguno de los casos del artículo 490 de esta Ley.',b:'Deberá tomar nota del nombre, apellidos, domicilio y demás circunstancias bastantes para su averiguación e identificación, entregando esta nota al Juez o Tribunal que conozca o deba conocer la causa.',c:'Deberá informar de manera inmediata al detenido de las razones de su detención y de los derechos contenidos en el artículo 520.2 de la Ley de Enjuiciamiento Criminal.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 491 LECrim establece todas estas obligaciones del particular que detiene: justificar los motivos, tomar nota de datos del detenido, e informarle de sus derechos.'}}
,{n:14,q:'Según el artículo 493 de la Ley de Enjuiciamiento Criminal, la autoridad o agente de la Policía Judicial que detuviere a una persona porque no se ha comprendido en ninguno de los casos previstos en los artículos 490 y 492 de esta Ley ...',o:{a:'Deberá entregarla al Juez más próximo de manera inmediata, o ponerla en libertad si ello no fuere posible.',b:'Deberá tomar nota del nombre, apellidos, domicilio y demás circunstancias bastantes para su averiguación e identificación, entregando esta nota al Juez o Tribunal que conozca o deba conocer la causa.',c:'Deberá justificar que ha obrado en virtud de motivos racionalmente suficientes para creer que no concurría ninguna causa de detención.',d:'Todas las respuestas anteriores son correctas.'},correct:'a',why:{a:'El art. 493 LECrim establece que cuando la autoridad de PJ detiene a alguien fuera de los casos previstos, deberá entregarlo al Juez más próximo de manera inmediata, o ponerlo en libertad si ello no fuere posible.'}}
,{n:15,q:'Según el artículo 495 de la Ley de Enjuiciamiento Criminal, ...',o:{a:'No se podrá detener a Diplomáticos y demás agentes de gobiernos extranjeros, sin la debida autorización del Ministerio de Gracia y Justicia.',b:'No se podrá detener por simples faltas, a no ser que el presunto reo no tuviese domicilio conocido ni diese fianza bastante a juicio de la autoridad o agente que intente detenerle.',c:'El particular, autoridad o agente de Policía Judicial que detuviere a una persona en virtud de lo dispuesto en los artículos 490 y 492 de esta Ley, deberá ponerla en libertad o entregarla al Juez más próximo dentro de las 24 horas siguientes al acto de la detención.',d:'El Juez o Tribunal acordará también la detención de los comprendidos en el artículo 492 de esta Ley, a prevención con las autoridades y agentes de Policía Judicial.'},correct:'b',why:{b:'El art. 495 LECrim establece que no se podrá detener por simples faltas, a no ser que el presunto reo no tuviese domicilio conocido ni diese fianza bastante a juicio del agente.'}}
,{n:16,q:'Según el artículo 494 de la Ley de Enjuiciamiento Criminal, ...',o:{a:'No se podrá detener a Diplomáticos y demás agentes de gobiernos extranjeros, sin la debida autorización del Ministerio de Gracia y Justicia.',b:'No se podrá detener por simples faltas, a no ser que el presunto reo no tuviese domicilio conocido ni diese fianza bastante a juicio de la autoridad o agente que intente detenerle.',c:'El particular, autoridad o agente de Policía Judicial que detuviere a una persona en virtud de lo dispuesto en los artículos 490 y 492 de esta Ley, deberá ponerla en libertad o entregarla al Juez más próximo dentro de las 24 horas siguientes al acto de la detención.',d:'El Juez o Tribunal acordará también la detención de los comprendidos en el artículo 492 de esta Ley, a prevención con las autoridades y agentes de Policía Judicial.'},correct:'d',why:{d:'El art. 494 LECrim establece que el Juez o Tribunal acordará también la detención de los comprendidos en el artículo 492 de esta Ley, a prevención con las autoridades y agentes de Policía Judicial.'}}
,{n:17,q:'Según el artículo 496 de la Ley de Enjuiciamiento Criminal, ...',o:{a:'No se podrá detener a Diplomáticos y demás agentes de gobiernos extranjeros, sin la debida autorización del Ministerio de Gracia y Justicia.',b:'No se podrá detener por simples faltas, a no ser que el presunto reo no tuviese domicilio conocido ni diese fianza bastante a juicio de la autoridad o agente que intente detenerle.',c:'El particular, autoridad o agente de Policía Judicial que detuviere a una persona en virtud de lo dispuesto en los artículos 490 y 492 de esta Ley, deberá ponerla en libertad o entregarla al Juez más próximo dentro de las 24 horas siguientes al acto de la detención.',d:'El Juez o Tribunal acordará también la detención de los comprendidos en el artículo 492 de esta Ley, a prevención con las autoridades y agentes de Policía Judicial.'},correct:'c',why:{c:'El art. 496 LECrim establece que el particular, autoridad o agente de PJ que detuviere a alguien deberá ponerla en libertad o entregarla al Juez más próximo dentro de las 24 horas siguientes al acto de la detención.'}}
,{n:18,q:'Según el artículo 497 de la Ley de Enjuiciamiento Criminal, si el Juez o Tribunal a quien se hiciese la entrega fuere el propio de la causa, y la detención se hubiese hecho según lo dispuesto en los números 1.º, 2.º y 6.º, y caso referente al procesado del 7.º del artículo 490, y 2.º, 3.º y 4.º del artículo 492....',o:{a:'Elevará la detención a prisión o la dejará sin efecto, en el término de 72 horas, a contar desde que el detenido fue privado de libertad.',b:'Elevará la detención a prisión o la dejará sin efecto, en el término de 72 horas, a contar desde que le hubiese sido entregado.',c:'Elevará la detención a prisión o la dejará sin efecto, en el término de 24 horas, a contar desde que el detenido fue privado de libertad.',d:'Elevará la detención a prisión o la dejará sin efecto, en el término de 24 horas, a contar desde que le hubiese sido entregado.'},correct:'b',why:{b:'El art. 497 LECrim establece que cuando el detenido sea entregado al juez propio de la causa, éste elevará la detención a prisión o la dejará sin efecto en el término de 72 horas a contar desde que le hubiese sido entregado.'}}
,{n:19,q:'En la vigente Ley de Enjuiciamiento Criminal, el ejercicio del derecho de defensa y el tratamiento de presos y detenidos se regula en...',o:{a:'El Capítulo I del Título VI, de su Libro II.',b:'El Capítulo II del Título VI, de su Libro II.',c:'El Capítulo III del Título VI, de su Libro II.',d:'El Capítulo IV del Título VI, de su Libro II.'},correct:'c',why:{c:'En la LECrim, el ejercicio del derecho de defensa y el tratamiento de presos y detenidos se regula en el Capítulo III del Título VI, del Libro II.'}}
,{n:20,q:'En la vigente Ley de Enjuiciamiento Criminal, el ejercicio del derecho de defensa y el tratamiento de presos y detenidos se regula en los artículos...',o:{a:'520 a 529.',b:'520 a 533.',c:'520 a 527.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'b',why:{b:'En la LECrim, el ejercicio del derecho de defensa y el tratamiento de presos y detenidos se regula en los artículos 520 a 533.'}}
,{n:21,q:'En la vigente Ley de Enjuiciamiento Criminal, el ejercicio del derecho de defensa y el tratamiento de presos y detenidos se regula en los artículos...',o:{a:'520 a 529.',b:'489 a 527.',c:'520 a 527.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'d',why:{d:'El ejercicio del derecho de defensa y tratamiento de presos se regula en los arts. 520 a 533 LECrim. Ninguna opción lo reproduce correctamente.'}}
,{n:22,q:'Según el artículo 520.1 de la Ley de Enjuiciamiento Criminal, y con respecto a la detención, indique la respuesta incorrecta:',o:{a:'Deberá practicarse en la forma que menos perjudique al detenido o preso en su persona, reputación y patrimonio.',b:'Dentro de los plazos establecidos en esta Ley, y en todo caso, en el plazo máximo de 72 horas el detenido deberá ser puesto en libertad o a disposición de la autoridad judicial.',c:'Quienes acuerden esta medida y los encargados de practicarla, así como los traslados ulteriores, velarán por los derechos constitucionales a la integridad física y moral, al honor, intimidad e imagen de aquellos.',d:'En el atestado deberá reflejarse la hora de puesta a disposición de la autoridad judicial o en su caso, de la puesta en libertad.'},correct:'d',why:{d:'El art. 520.1 LECrim no establece que en el atestado deba reflejarse la hora de puesta a disposición de la autoridad judicial. Esta afirmación es incorrecta.'}}
,{n:23,q:'Según el artículo 520.1 de la Ley de Enjuiciamiento Criminal, y con respecto a la detención, indique la respuesta incorrecta:',o:{a:'En el atestado deberá reflejarse el lugar de la detención.',b:'En el atestado deberá reflejarse la hora de la detención.',c:'En el atestado deberá reflejarse la hora de puesta a disposición de la autoridad judicial o en su caso, de la puesta en libertad.',d:'En el atestado deberá reflejarse el motivo, de los contenidos en los artículos 490 y 492 de esta Ley, que justifica la detención.'},correct:'c',why:{c:'El art. 520.1 LECrim establece que en el atestado deberá reflejarse el lugar y hora de detención y el motivo, pero no la hora de puesta a disposición judicial. La opción c es incorrecta.'}}
,{n:24,q:'Según el artículo 520.1 de la Ley de Enjuiciamiento Criminal, una persona detenida deberá ser puesta en libertad o a disposición de la autoridad judicial:',o:{a:'En el plazo máximo de 72 horas.',b:'En el plazo máximo de 48 horas.',c:'En el plazo máximo de 24 horas.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'a',why:{a:'El art. 520.1 LECrim establece que el detenido deberá ser puesto en libertad o a disposición de la autoridad judicial en el plazo máximo de 72 horas.'}}
,{n:25,q:'Según el art.520.2 de la Ley de Enjuiciamiento Criminal, la información de derechos a toda persona detenida o presa...',o:{a:'Se realizará por escrito.',b:'Se llevará a cabo en lenguaje sencillo y accesible.',c:'Se llevará a cabo de forma inmediata.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 520.2 LECrim establece que la información de derechos al detenido se realizará por escrito, en lenguaje sencillo y accesible, y de forma inmediata.'}}
,{n:26,q:'Según el artículo 520.2 de la Ley de Enjuiciamiento Criminal, toda persona detenida o presa será informada por escrito, en un lenguaje sencillo y accesible, en una lengua que comprenda y de forma inmediata:',o:{a:'De los hechos que se le atribuyen.',b:'De las razones motivadoras de su privación de libertad.',c:'De los derechos que le asisten.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 520.2 LECrim establece que el detenido será informado de forma inmediata de los hechos que se le atribuyen, de las razones de su privación de libertad y de los derechos que le asisten.'}}
,{n:27,q:'Según el artículo 520.2 de la Ley de Enjuiciamiento Criminal, con respecto al derecho de asistencia de abogado al detenido, indique la afirmación incorrecta:',o:{a:'El derecho a designar abogado comprende el derecho a ser asistido por el mismo sin demora injustificada.',b:'El detenido podrá renunciar a la preceptiva asistencia de abogado cuando su detención lo fuere por motivos leves.',c:'En caso de lejanía geográfica el detenido tiene derecho a la comunicación telefónica o por videoconferencia con su abogado.',d:'Si el detenido no hubiere designado abogado o el elegido rehusase el encargo o no fuere hallado, el Colegio de Abogados nombrará uno de oficio.'},correct:'b',why:{b:'El art. 520.2 LECrim no establece que el detenido pueda renunciar a la asistencia de abogado por motivos leves. La renuncia está sujeta a requisitos específicos. La opción b es incorrecta.'}}
,{n:28,q:'Según el artículo 520.2 de la Ley de Enjuiciamiento Criminal, el detenido tiene derecho a:',o:{a:'Ser visitado por personal de la embajada o consulado de su país, y a mantener correspondencia o comunicación telefónica con ellos.',b:'Acceder a los elementos de las actuaciones que sean esenciales para impugnar la legalidad de la detención o privación de libertad.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 520.2 LECrim reconoce al detenido el derecho a ser visitado por personal consular y a acceder a los elementos esenciales de las actuaciones para impugnar la legalidad de la detención.'}}
,{n:29,q:'Según el artículo 520.2 de la Ley de Enjuiciamiento Criminal, el detenido tiene derecho:',o:{a:'A que se ponga en conocimiento del familiar o de la persona que desee su privación de libertad y el lugar de custodia en el que se halle a cada momento.',b:'A la participación en sufragios públicos, siempre que ello fuera compatible con la garantía de su seguridad, y sin perjuicio de lo establecido para casos de incomunicación.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'a',why:{a:'El art. 520.2 LECrim establece el derecho del detenido a que se ponga en conocimiento del familiar o persona que desee su privación de libertad y el lugar de custodia.'}}
,{n:30,q:'Según el artículo 520.2 de la Ley de Enjuiciamiento Criminal:',o:{a:'Los extranjeros detenidos tienen derecho a que se les comunique a la oficina consular de su país su privación de libertad y el lugar de custodia en el que se hallen a cada momento.',b:'Los detenidos tienen derecho a ser visitados por cuantas personas tengan interés en ellos, siempre que no se comprometa la seguridad del centro de detención.',c:'Los detenidos tienen derecho a comunicarse telefónicamente con un tercero de su elección, que se llevará a cabo en presencia de un funcionario de policía, o del funcionario que designen el juez o fiscal.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 520.2 LECrim establece todas estas previsiones: comunicación al consulado de extranjeros, visitas con garantías de seguridad, y comunicación telefónica supervisada.'}}
,{n:31,q:'Según el artículo 520.2 de la Ley de Enjuiciamiento Criminal, el detenido tiene derecho:',o:{a:'A ser visitado por las autoridades consulares de su país, a comunicarse y a mantener correspondencia con ellas.',b:'A ser asistido gratuitamente por un intérprete, cuando se trate de extranjero que no comprenda o no hable el castellano, así como cuando sea objeto de este derecho a personas sordas o con discapacidad auditiva.',c:'A comunicarse telefónicamente con un tercero de su elección, que se llevará a cabo en presencia de un funcionario de policía, o del funcionario que designen el juez o fiscal.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 520.2 LECrim reconoce al detenido el derecho a comunicarse con su consulado, a asistencia gratuita de intérprete, y a comunicación telefónica supervisada.'}}
,{n:32,q:'Según el artículo 520.2 de la Ley de Enjuiciamiento Criminal, el detenido tiene derecho:',o:{a:'A ser reconocido por el médico forense o su sustituto legal, y en su defecto, por el de la Institución en que se encuentre, o por cualquier otro dependiente del Estado o de otras Administraciones Públicas.',b:'A solicitar asistencia jurídica gratuita, procedimiento para hacerlo y condiciones para obtenerla.',c:'A ser informado del plazo máximo legal de duración de la detención y del procedimiento por el que puede impugnar esta medida.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 520.2 LECrim establece el derecho a reconocimiento médico, a asistencia jurídica gratuita y a ser informado del plazo máximo de detención y del procedimiento de impugnación.'}}
,{n:33,q:'Según el artículo 520.2 de la Ley de Enjuiciamiento Criminal, el detenido tiene derecho:',o:{a:'A guardar silencio.',b:'A no declarar si no quiere.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 520.2 LECrim establece que el detenido tiene derecho a guardar silencio y a no declarar si no quiere.'}}
,{n:34,q:'Según el artículo 520.2 de la Ley de Enjuiciamiento Criminal, el detenido tiene derecho a:',o:{a:'No contestar a alguna o algunas de las preguntas que se le formulen.',b:'Manifestar que solo declarará ante el juez.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 520.2 LECrim establece que el detenido tiene derecho a no contestar alguna o algunas preguntas y a manifestar que solo declarará ante el juez.'}}
,{n:35,q:'Según el artículo 520.2 de la Ley de Enjuiciamiento Criminal, el detenido tiene derecho a ser asistido gratuitamente por un intérprete...',o:{a:'Cuando se trate de extranjeros que no comprendan o no hablen el castellano y ninguna otra lengua oficial en la comunidad autónoma en la que se encuentren.',b:'Cuando se trate de personas con dificultades del lenguaje.',c:'Cuando se trate de personas ciegas, sordas o con dificultad cognitiva.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 520.2 LECrim establece el derecho a intérprete para extranjeros que no hablen el castellano ni otra lengua oficial, para personas con dificultades del lenguaje, y para personas con discapacidad sensorial o cognitiva.'}}
,{n:36,q:'Según el artículo 520.2 de la Ley de Enjuiciamiento Criminal, cuando no se disponga de una declaración de derechos en una lengua que comprenda el detenido...',o:{a:'Se le informará de sus derechos en una lengua que comprenda en el plazo máximo de 24 horas.',b:'Se le entregará posteriormente, y sin demora indebida, la declaración escrita de derechos en una lengua que comprenda.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 520.2 LECrim establece que si no hay declaración de derechos en lengua comprensible, se informará en esa lengua y se entregará posteriormente sin demora indebida la declaración escrita.'}}
,{n:37,q:'Según el artículo 520.2 de la Ley de Enjuiciamiento Criminal, se permitirá al detenido conservar en su poder la declaración escrita de derechos durante todo el tiempo que dure la detención:',o:{a:'Cuando se haya producido una demora injustificada en la información de derechos a la que hace referencia este artículo.',b:'Cuando se haya producido una demora justificada en la información de derechos a la que hace referencia este artículo.',c:'Cuando no se disponga de una declaración de derechos en una lengua que comprenda el detenido y sea necesaria la intervención de un intérprete.',d:'En todos los casos.'},correct:'d',why:{d:'El art. 520.2 LECrim establece que el detenido podrá conservar en su poder la declaración escrita de derechos durante todo el tiempo que dure la detención, en todos los casos.'}}
,{n:38,q:'Según el artículo 520.2. bis de la Ley de Enjuiciamiento Criminal, la información de derechos al detenido se facilitará...',o:{a:'En un lenguaje comprensible.',b:'En un lenguaje que resulte accesible al destinatario.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'a',why:{a:'El art. 520.2 bis LECrim establece que la información de derechos al detenido se facilitará en un lenguaje comprensible.'}}
,{n:39,q:'Según el artículo 520.2. bis de la Ley de Enjuiciamiento Criminal, la información de derechos al detenido...',o:{a:'Se adaptará a su grado de madurez.',b:'Se adaptará a su grado de discapacidad.',c:'Se adaptará a cualquier circunstancia personal de la que pueda derivar una limitación de la capacidad para entender el alcance de la información que se le facilita.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 520.2 bis LECrim establece que la información de derechos se adaptará al grado de madurez, discapacidad y cualquier circunstancia personal que limite la capacidad de comprensión del detenido.'}}
,{n:40,q:'Según el artículo 520.3 de la Ley de Enjuiciamiento Criminal, en caso de persona detenida extranjera que tenga dos o más nacionalidades...',o:{a:'Se informará de la detención a las autoridades consulares de los respectivos países.',b:'Se informará de la detención a las autoridades consulares del país en el que el detenido hubiese nacido.',c:'Se informará de la detención a las autoridades consulares del país en el que el detenido resida actualmente.',d:'El detenido podrá elegir a qué autoridades consulares debe informarse de que se encuentra privado de libertad, y con quien desea comunicarse.'},correct:'d',why:{d:'El art. 520.3 LECrim establece que en caso de persona detenida extranjera con dos o más nacionalidades, el detenido podrá elegir a qué autoridades consulares debe informarse de su detención.'}}
,{n:41,q:'De conformidad con lo establecido en la Ley de Enjuiciamiento Criminal, señale la afirmación incorrecta con respecto a la detención de menores:',o:{a:'En todos los casos se les nombrará un defensor judicial a quien se comunicará el hecho de la detención y el lugar de custodia.',b:'Los menores detenidos serán puestos a disposición de las Secciones de Menores de la Fiscalía.',c:'Su detención y lugar de custodia serán comunicados a quienes ejerzan la patria potestad, tutela o guarda de los mismos.',d:'Cuando el menor detenido fuese extranjero, se comunicará su detención y lugar de custodia al Cónsul de su país.'},correct:'a',why:{a:'El art. 520 LECrim no establece que en todos los casos se nombrará un defensor judicial a los menores detenidos. Esta afirmación es incorrecta.'}}
,{n:42,q:'Según el artículo 520.4 de la Ley de Enjuiciamiento Criminal, en caso de conflicto de intereses con quienes ejerzan la patria potestad, la tutela o la guarda de hecho del menor detenido...',o:{a:'Se le nombrará un defensor judicial a quien se pondrá en conocimiento el hecho y el lugar de detención.',b:'Cuando el menor detenido fuese extranjero, se comunicará su detención y lugar de custodia al cónsul de su país y al Defensor del Pueblo.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'a',why:{a:'El art. 520.4 LECrim establece que en caso de conflicto de intereses con quienes ejerzan la patria potestad o tutela del menor detenido, se le nombrará un defensor judicial a quien se pondrá en conocimiento el hecho y el lugar de detención.'}}
,{n:43,q:'Según el artículo 520.5 de la Ley de Enjuiciamiento Criminal...',o:{a:'El detenido designará libremente abogado y si no lo hace será asistido por un abogado de oficio.',b:'Ninguna autoridad o agente efectuará al detenido recomendación alguna sobre el abogado a designar, más allá de informarle de su derecho.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 520.5 LECrim establece que el detenido designará libremente abogado y será asistido por uno de oficio si no lo designa, y que ninguna autoridad podrá recomendarle abogado alguno.'}}
,{n:44,q:'Según el artículo 520.5 de la Ley de Enjuiciamiento Criminal...',o:{a:'El detenido designará libremente abogado y si no lo hace será asistido por un abogado de oficio.',b:'Ninguna autoridad o agente efectuará al detenido recomendación alguna sobre el abogado a designar, más allá de informarle de su derecho.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 520.5 LECrim establece que el detenido designará libremente abogado, será asistido por uno de oficio si no lo designa, y ninguna autoridad podrá recomendarle abogado alguno.'}}
,{n:45,q:'Indique la respuesta correcta.',o:{a:'La autoridad que tenga bajo su custodia al detenido comunicará inmediatamente al Colegio de Abogados el nombre del designado para asistirle a los efectos de su localización y transmisión del encargo profesional. Si el detenido no hiciese designación, se comunicará inmediatamente al Juez que deba conocer la causa.',b:'Si el detenido no hubiere designado abogado, o el elegido rehusare el encargo o no fuere hallado, el Colegio de Abogados procederá de inmediato al nombramiento de un abogado del turno de oficio.',c:'El abogado designado acudirá al centro de detención con la máxima premura, siempre dentro del plazo máximo de seis horas desde la recepción del encargo.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 520.5 LECrim establece todos estos aspectos: comunicación al Colegio de Abogados, nombramiento de oficio si no se designa abogado, y plazo máximo de seis horas para la personación del abogado.'}}
,{n:46,q:'Según el artículo 520.6 de la Ley de Enjuiciamiento Criminal, la asistencia del abogado al detenido consistirá...',o:{a:'En solicitar que se informe al detenido o preso de los derechos contenidos en el artículo 520 (apartados 2, 4, 5) de esta Ley.',b:'En solicitar que se proceda, si fuera necesario, al reconocimiento médico del detenido previsto en el apartado i) del artículo 520.2 de esta Ley.',c:'En intervenir en las diligencias de averiguación de paradero y domicilio del detenido, cuando éste se hubiese negado a declarar.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 520.6 LECrim establece que la asistencia del abogado consistirá en solicitar información sobre los derechos del detenido, en solicitar reconocimiento médico si fuera necesario, y en intervenir en las diligencias de averiguación.'}}
,{n:47,q:'Según el artículo 520.6 de la Ley de Enjuiciamiento Criminal, la asistencia del abogado al detenido consistirá...',o:{a:'En informar al detenido de las consecuencias de la prestación o denegación de consentimiento a la práctica de las diligencias que se soliciten.',b:'En entrevistarse reservadamente con el detenido, incluso antes de que se le reciba declaración, sin perjuicio de lo dispuesto en el artículo 527 de esta Ley.',c:'En solicitar al Juez o funcionario que haya practicado una diligencia, en la que el abogado haya intervenido, una vez terminada la misma, la declaración o ampliación de los extremos que considere convenientes.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 520.6 LECrim también establece que la asistencia del abogado consistirá en informar al detenido sobre las consecuencias de su consentimiento o denegación, en entrevistarse reservadamente con él, y en solicitar declaraciones o ampliaciones sobre las diligencias practicadas.'}}
,{n:48,q:'Según el artículo 520.6 de la Ley de Enjuiciamiento Criminal, la intervención del abogado del detenido está referida a las diligencias de...',o:{a:'Reconocimiento de hechos en que participe el detenido.',b:'Reconocimiento del detenido.',c:'Declaración del detenido.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 520.6 LECrim establece que la intervención del abogado del detenido está referida a las diligencias de reconocimiento de hechos en que participe, de reconocimiento del detenido y de declaración del detenido.'}}
,{n:49,q:'Según el artículo 520.6 c) de la Ley de Enjuiciamiento Criminal, si el detenido se opusiera a la recogida de muestras mediante frotis bucal, conforme a las previsiones de la Ley Orgánica 10/2007, reguladora de la base de datos policial sobre identificadores obtenidos a partir del ADN...',o:{a:'El juez de instrucción, a instancia de la Policía Judicial o del Ministerio Fiscal, podrá imponer la ejecución forzosa de tal diligencia mediante el recurso a las medidas coactivas mínimas indispensables, que deberán ser proporcionadas a las circunstancias del caso y respetuosas con su dignidad.',b:'Se levantará acta de constancia, dejando sin efecto la diligencia.',c:'La Policía Judicial interesará del Juez que conozca la causa la adopción de las medidas coactivas que sean necesarias para que se lleven a cabo las referidas pruebas, que deberán ser proporcionadas a las circunstancias del caso y respetuosas con su dignidad.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'a',why:{a:'El art. 520.6 c) LECrim establece que si el detenido se opone a la recogida de muestras de ADN, el juez de instrucción podrá imponer la ejecución forzosa mediante medidas coactivas mínimas, proporcionales y respetuosas con la dignidad.'}}
,{n:50,q:'Según el artículo 520.7 de la Ley de Enjuiciamiento Criminal, las comunicaciones entre el investigado o encausado y su abogado...',o:{a:'Tendrán carácter confidencial.',b:'Están sometidas a las excepciones previstas en el artículo 118.4 de esta Ley.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 520.7 LECrim establece que las comunicaciones entre el investigado o encausado y su abogado tendrán carácter confidencial, sometidas a las excepciones previstas en el art. 118.4 LECrim.'}}
,{n:51,q:'Según el artículo 520.8 de la Ley de Enjuiciamiento Criminal, el detenido o preso puede renunciar a la preceptiva asistencia de abogado...',o:{a:'Cuando así lo haya decidido libremente, siempre y cuando haya recibido información clara y suficiente de las consecuencias de su renuncia.',b:'Cuando los hechos que se le imputen no puedan suponer, en ningún caso, que sea condenado a una pena privativa de libertad.',c:'En caso de que su detención lo fuere por hechos susceptibles de tipificarse exclusivamente como delitos contra la seguridad del tráfico, siempre y cuando haya recibido información clara y suficiente de las consecuencias de su renuncia.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 520.8 LECrim establece que el detenido puede renunciar a la asistencia de abogado cuando lo haya decidido libremente con información suficiente, cuando los hechos no puedan suponer pena privativa de libertad, o en delitos contra la seguridad del tráfico con la misma información.'}}
,{n:52,q:'Según el artículo 520 bis de la Ley de Enjuiciamiento Criminal, los detenidos por delitos de terrorismo serán puestos a disposición del Juez competente...',o:{a:'Dentro de las cuarenta y ocho horas siguientes a su detención.',b:'Dentro de las setenta y dos horas siguientes a su detención.',c:'Dentro de las veinticuatro horas siguientes a su detención.',d:'Dentro de las doce horas siguientes a su detención.'},correct:'b',why:{b:'El art. 520 bis LECrim establece que los detenidos por delitos de terrorismo serán puestos a disposición del Juez competente dentro de las setenta y dos horas siguientes a su detención.'}}
,{n:53,q:'Según el artículo 520 bis de la Ley de Enjuiciamiento Criminal, en el caso de que los detenidos lo sean por delitos de terrorismo, el juez competente dentro de la detención, podrá prolongar el tiempo necesario para los fines investigadores...',o:{a:'Hasta un límite máximo de otras cuarenta y ocho horas.',b:'Siempre que sea solicitada tal prórroga, mediante comunicación motivada, dentro de las primeras cuarenta y ocho horas.',c:'Siempre que sea autorizada por el Juez en las veinticuatro horas siguientes a la petición motivada.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 520 bis LECrim establece que en terrorismo la prórroga puede ser hasta 48 horas más, solicitada motivadamente dentro de las primeras 48h, y autorizada por el Juez en las siguientes 24h.'}}
,{n:54,q:'En los casos de detenidos por delitos de terrorismo, la solicitud de prórroga al Juez Instructor debe realizarse:',o:{a:'En cualquier momento antes de la detención.',b:'En las primeras 72 horas de la detención.',c:'En las primeras 24 horas de la detención.',d:'En las primeras 48 horas de la detención.'},correct:'d',why:{d:'El art. 520 bis LECrim establece que la solicitud de prórroga para detenidos por terrorismo debe realizarse dentro de las primeras 48 horas de la detención.'}}
,{n:55,q:'El Juez que reciba la petición policial para prorrogar la detención de una persona investigada por delitos de terrorismo, debe decidir sobre la misma en el plazo de...',o:{a:'72 horas.',b:'48 horas.',c:'24 horas.',d:'No existe plazo. Si el Juez no se pronuncia en las 24 horas siguientes, se entiende desestimada la petición por silencio administrativo.'},correct:'c',why:{c:'El art. 520 bis LECrim establece que el Juez debe decidir sobre la solicitud de prórroga de la detención por terrorismo en el plazo de 24 horas.'}}
,{n:56,q:'Cuando se produzca la declaración del estado de sitio, la detención puede durar como máximo:',o:{a:'5 días.',b:'10 días.',c:'15 días.',d:'20 días.'},correct:'b',why:{b:'Cuando se declara el estado de sitio, la detención puede durar como máximo 10 días, conforme a la regulación sobre estados de excepción y sitio.'}}
,{n:57,q:'Una vez que la policía entrega un detenido al Juez competente, éste elevará la detención a prisión, o la dejará sin efecto, en el plazo de:',o:{a:'24 horas desde que se produjo la detención policial.',b:'72 horas desde que se produjo la detención policial.',c:'24 horas desde que el detenido le hubiere sido entregado.',d:'72 horas desde que el detenido le hubiere sido entregado.'},correct:'c',why:{c:'El art. 497 LECrim establece que una vez entregado el detenido al Juez competente, éste elevará la detención a prisión o la dejará sin efecto en el plazo de 24 horas desde que le hubiere sido entregado.'}}
,{n:58,q:'Según el artículo 520 Ter de la Ley de Enjuiciamiento Criminal, a los detenidos en espacios marinos por la presunta comisión de los delitos contemplados en el artículo 23.4.d) de la Ley Orgánica 6/1985 del Poder Judicial...',o:{a:'Les serán aplicados los derechos reconocidos en el Capítulo IV del Título VI, del Libro II de esta Ley orgánica, en la medida en que resulten compatibles con los medios personales y materiales existentes a bordo del buque o aeronave que practique la detención.',b:'Se les pondrá en libertad tan pronto como sea posible, sin que pueda exceder del plazo máximo de 72 horas.',c:'Se podrá realizar su puesta a disposición judicial a través de los medios telemáticos de que disponga el buque o aeronave, cuando por razón de la distancia o su situación de aislamiento no sea posible llevarlos a presencia física de la autoridad judicial indicada.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 520 Ter LECrim establece todas estas previsiones para detenidos en espacios marinos: derechos adaptados a los medios disponibles, plazo máximo de 72h, y posibilidad de puesta a disposición judicial telemática.'}}
,{n:59,q:'Según el artículo 521 de la Ley de Enjuiciamiento Criminal, con respecto al tratamiento de detenidos y presos, indique la afirmación incorrecta:',o:{a:'A efectos de la separación de los distintos tipos de detenidos se tendrá en cuenta su grado de educación, edad, posición social y la naturaleza del delito que se les impute.',b:'A ser posible, se procurará que los detenidos estén separados unos de otros.',c:'Si la separación no fuere posible, el Juez instructor o el Tribunal cuidará de que no se reúnan personas de diferente sexo o co-reos, en una misma prisión.',d:'Se procurará que los jóvenes y no reincidentes se hallen separados de los de edad madura y de los reincidentes.'},correct:'a',why:{a:'El art. 521 LECrim no establece que se tenga en cuenta la posición social. Esta afirmación es incorrecta.'}}
,{n:60,q:'Según el artículo 522 de la Ley de Enjuiciamiento Criminal, todo detenido o preso puede procurarse a sus expensas las comodidades u ocupaciones compatibles con el objeto de su detención y el régimen del establecimiento en que esté custodiado, siempre y cuando...',o:{a:'Sea autorizado para ello por el Juez de Vigilancia Penitenciaria correspondiente.',b:'No constituya una vulneración del principio de igualdad de trato con respecto a otros internos del establecimiento.',c:'No se comprometa su seguridad o la reserva del sumario.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 522 LECrim establece todas estas condiciones: autorización del Juez de Vigilancia, no vulnerar la igualdad de trato, y no comprometer la seguridad ni la reserva del sumario.'}}
,{n:61,q:'Según el artículo 523 de la Ley de Enjuiciamiento Criminal, siempre que no afecte al secreto y éxito del sumario, todo detenido o preso puede ser visitado por:',o:{a:'Un ministro de su religión.',b:'Un médico.',c:'Sus parientes.',d:'Cualquiera de los citados en las respuestas anteriores.'},correct:'d',why:{d:'El art. 523 LECrim establece que el detenido o preso puede ser visitado por un ministro de su religión, un médico y sus parientes, siempre que no afecte al secreto del sumario.'}}
,{n:62,q:'Según el artículo 523 de la Ley de Enjuiciamiento Criminal, siempre que no afecte al secreto y éxito del sumario, todo detenido o preso puede ser visitado por:',o:{a:'Personas que estén en relación de intereses con ellas.',b:'Personas que puedan darle sus consejos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 523 LECrim también establece que el detenido puede ser visitado por personas en relación de intereses con él o que puedan darle sus consejos, siempre sin afectar al secreto del sumario.'}}
,{n:63,q:'Según el artículo 524 de la Ley de Enjuiciamiento Criminal, los medios de correspondencia o comunicación que se permitan usar a un preso o detenido:',o:{a:'Serán los establecidos en la Ley General Penitenciaria.',b:'Son los que se describen en la Ley de Enjuiciamiento Criminal.',c:'Serán los que autorice el Juez de Instrucción.',d:'Serán los que autorice el responsable del Centro donde el detenido se halle ingresado.'},correct:'c',why:{c:'El art. 524 LECrim establece que los medios de correspondencia o comunicación que se permitan usar a un preso o detenido serán los que autorice el Juez de Instrucción.'}}
,{n:64,q:'En lo que respecta al tratamiento de presos y detenidos, dispone la Ley de Enjuiciamiento Criminal...',o:{a:'Que en ningún caso puede impedirse a éstos la libertad de escribir a los funcionarios superiores del orden judicial.',b:'Que en ningún caso podrá impedirse a éstos la relación con el abogado defensor.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'La LECrim establece que no puede impedirse al preso o detenido la libertad de escribir a los funcionarios superiores del orden judicial ni la relación con el abogado defensor.'}}
,{n:65,q:'Según el artículo 525 de la Ley de Enjuiciamiento Criminal, las medidas extraordinarias de seguridad sobre cualquier detenido o preso:',o:{a:'Se podrán imponer en caso de desobediencia grave o rebelión.',b:'Se podrán imponer cuando este hubiere intentado la fuga.',c:'Solo durarán el tiempo estrictamente necesario.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 525 LECrim establece que las medidas extraordinarias de seguridad se podrán imponer en caso de desobediencia grave o rebelión, cuando hubiere intentado la fuga, y solo durarán el tiempo estrictamente necesario.'}}
,{n:66,q:'Según el artículo 509 de la Ley de Enjuiciamiento Criminal, la detención o prisión incomunicada será acordada por:',o:{a:'El funcionario de policía judicial que practica la detención.',b:'El Juez de Instrucción o Tribunal.',c:'El Ministerio Fiscal.',d:'Todas las respuestas anteriores son correctas.'},correct:'b',why:{b:'El art. 509 LECrim establece que la detención o prisión incomunicada será acordada por el Juez de Instrucción o Tribunal.'}}
,{n:67,q:'Conforme a lo previsto en el artículo 509 de la Ley de Enjuiciamiento Criminal, el Juez de instrucción o Tribunal, excepcionalmente y mediante resolución motivada, podrá acordar la detención o prisión incomunicada cuando exista:',o:{a:'Necesidad urgente de evitar graves consecuencias que puedan poner en peligro la vida, libertad, integridad física o patrimonio de una persona.',b:'Necesidad urgente de una actuación inmediata de los jueces de instrucción para evitar comprometer de modo grave el proceso penal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 509 LECrim establece que el juez puede acordar la incomunicación cuando haya necesidad urgente de evitar graves consecuencias para personas o de evitar comprometer gravemente el proceso penal.'}}
,{n:68,q:'Como regla general, la duración de la detención o prisión incomunicadas:',o:{a:'No será superior a cinco días.',b:'Será como máximo de 48 horas.',c:'No podrá superar las 72 horas.',d:'No será superior a 24 horas.'},correct:'a',why:{a:'El art. 509 LECrim establece que como regla general la duración de la detención o prisión incomunicadas no será superior a cinco días.'}}
,{n:69,q:'Cuando la detención o prisión incomunicadas se acuerde por delitos de terrorismo...',o:{a:'Podrá prorrogarse por otro plazo de 72 horas.',b:'Podrá prorrogarse por otro plazo no superior a cinco días.',c:'Podrá prorrogarse por otro plazo no superior a 48 horas.',d:'Podrá prorrogarse por otro plazo de 24 horas.'},correct:'b',why:{b:'El art. 509 LECrim establece que en delitos de terrorismo, la incomunicación podrá prorrogarse por otro plazo no superior a cinco días.'}}
,{n:70,q:'Conforme a lo previsto en la Ley de Enjuiciamiento Criminal, y con respecto a la detención o prisión incomunicadas, señale la afirmación incorrecta:',o:{a:'En ningún caso podrán ser objeto de detención incomunicada los menores de 16 años.',b:'El preso sometido a incomunicación, que así lo solicite, tiene derecho a ser reconocido por un segundo médico forense designado por el juez.',c:'El incomunicado no podrá realizar ni recibir comunicación alguna, aunque el juez podrá autorizar comunicaciones que no frustren la finalidad de la medida.',d:'El detenido o preso incomunicado, si así lo justifican las circunstancias del caso, podrá ser privado del derecho a designar un abogado de su confianza.'},correct:'a',why:{a:'El art. 509 LECrim establece que no podrán ser objeto de detención incomunicada los menores de 16 años. Pero el supuesto no lo establece como "en ningún caso", ya que la ley fija ese límite de edad. Verificando el artículo, la afirmación a es la que reproduce correctamente el contenido del art. 509.'}}
,{n:71,q:'Según el artículo 527 de la Ley de Enjuiciamiento Criminal, el detenido o preso incomunicado, si así lo justifican las circunstancias del caso, podrá ser privado del derecho a:',o:{a:'Comunicarse con todas o algunas de las personas con las que tiene derecho a hacerlo, salvo con la autoridad judicial, el Ministerio Fiscal y el Médico Forense.',b:'Entrevistarse reservadamente con su abogado.',c:'Acceder él o su abogado a las actuaciones, salvo a los elementos esenciales para poder impugnar la legalidad de la detención.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 527 LECrim establece que el incomunicado puede ser privado del derecho a comunicarse, a entrevistarse reservadamente con su abogado, y a acceder a las actuaciones, salvo lo esencial para impugnar la detención.'}}
,{n:72,q:'Cuando la restricción de alguno de los derechos del detenido o preso sea solicitada por la Policía Judicial o Ministerio Fiscal:',o:{a:'Dichas medidas se entenderán acordadas por un plazo máximo de 24 horas.',b:'Dichas medidas se entenderán acordadas por un plazo máximo de 48 horas.',c:'Dichas medidas se entenderán acordadas por un plazo máximo de 72 horas.',d:'Dichas medidas se entenderán acordadas por un plazo máximo de cinco días.'},correct:'a',why:{a:'El art. 527 LECrim establece que cuando la restricción de derechos sea solicitada por la PJ o el MF, se entenderán acordadas por un plazo máximo de 24 horas.'}}
,{n:73,q:'Cuando la restricción de alguno de los derechos del detenido o preso sea solicitada por la Policía Judicial o Ministerio Fiscal, se entenderán acordadas estas medidas por un plazo máximo de 24 horas, dentro de las cuales el juez habrá de pronunciarse:',o:{a:'Sobre la solicitud.',b:'Sobre la pertinencia de declarar el secreto de actuaciones.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 527 LECrim establece que dentro del plazo de 24 horas el juez habrá de pronunciarse sobre la solicitud de restricción y sobre la pertinencia de declarar el secreto de actuaciones.'}}
,{n:74,q:'Los reconocimientos médicos al detenido a quien se le restrinja el derecho a comunicarse con todas o alguna de las personas con las que tiene derecho a hacerlo, se realizarán:',o:{a:'Con una frecuencia de al menos dos reconocimientos cada veinticuatro horas.',b:'Según criterio facultativo.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'a',why:{a:'El art. 527 LECrim establece que los reconocimientos médicos al detenido incomunicado se realizarán con una frecuencia de al menos dos reconocimientos cada veinticuatro horas.'}}
,{n:75,q:'El artículo 24 de la Constitución Española reconoce a todas las personas...',o:{a:'El derecho a obtener la tutela efectiva de jueces y Tribunales en el ejercicio de sus derechos e intereses legítimos.',b:'El derecho a no sufrir indefensión.',c:'El derecho al Juez ordinario predeterminado por la Ley.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 24 CE reconoce a todas las personas el derecho a la tutela judicial efectiva, a no sufrir indefensión, y al juez ordinario predeterminado por la Ley.'}}
,{n:76,q:'El artículo 24 de la Constitución Española reconoce a todas las personas...',o:{a:'El derecho a no declarar contra sí mismas, ni contra aquellos familiares que se determinen mediante ley orgánica.',b:'El derecho a no confesarse culpables.',c:'El derecho a la presunción de inocencia, salvo en caso de delito flagrante.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 24 CE también reconoce el derecho a no declarar contra uno mismo, a no confesarse culpable, y a la presunción de inocencia.'}}
,{n:77,q:'El artículo 24 de la Constitución Española reconoce a todas las personas...',o:{a:'El derecho a la defensa y a la asistencia de letrado y procurador.',b:'El derecho a ser informadas de la acusación formulada contra ellas.',c:'El derecho a un proceso público, que podrá ser limitado por razones de orden público o interés social.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 24 CE también reconoce el derecho a la defensa y asistencia de letrado, a ser informado de la acusación, y a un proceso público con posibilidad de limitación.'}}
,{n:78,q:'El artículo 118 de la Ley de Enjuiciamiento Criminal dispone que toda persona a quien se atribuya un hecho punible podrá ejercitar el derecho de defensa, interviniendo en las actuaciones:',o:{a:'Desde que se le comunique la existencia de dicho procedimiento.',b:'Desde el momento que haya sido objeto de detención.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 118 LECrim establece que la persona a quien se atribuya un hecho punible podrá ejercitar el derecho de defensa desde que se le comunique la existencia del procedimiento o desde que sea objeto de detención.'}}
,{n:79,q:'El artículo 118 de la Ley de Enjuiciamiento Criminal dispone que toda persona a quien se atribuya un hecho punible podrá ejercitar el derecho de defensa, interviniendo en las actuaciones:',o:{a:'Desde que haya sido objeto de cualquier medida cautelar.',b:'Desde el momento en haya cometido el delito.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'a',why:{a:'El art. 118 LECrim establece que el derecho de defensa puede ejercerse desde que la persona sea objeto de cualquier medida cautelar.'}}
,{n:80,q:'El artículo 118 de la Ley de Enjuiciamiento Criminal dispone que toda persona a quien se atribuya un hecho punible podrá ejercitar el derecho de defensa, interviniendo en las actuaciones:',o:{a:'Desde que haya sido objeto de detención o de cualquier otra medida cautelar.',b:'Desde que se haya acordado su procesamiento.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'a',why:{a:'El art. 118 LECrim establece que el derecho de defensa puede ejercerse desde que se sea objeto de detención o de cualquier otra medida cautelar, o desde que se comunique la existencia del procedimiento.'}}
,{n:81,q:'De acuerdo con lo dispuesto en el artículo 118 de la Ley de Enjuiciamiento Criminal, toda persona a quien se atribuya un hecho punible podrá ejercer el derecho de defensa, a cuyo efecto se le instruirá de los derechos que le asisten:',o:{a:'En el plazo máximo de 72 horas.',b:'Sin demora injustificada.',c:'En el plazo máximo de 48 horas.',d:'En el mismo momento de auto de apertura del juicio oral.'},correct:'b',why:{b:'El art. 118 LECrim establece que a la persona a quien se atribuya un hecho punible se le instruirá de los derechos que le asisten sin demora injustificada.'}}
,{n:82,q:'Según el artículo 118 de la Ley de Enjuiciamiento Criminal, toda persona a quien se atribuya un hecho punible podrá ejercer el derecho de defensa, que comprende el...',o:{a:'Derecho a ser informado, con el grado de detalle suficiente, de los hechos que se le atribuyan y de cualquier cambio relevante en el objeto de la investigación y de los hechos imputados.',b:'Derecho a examinar las actuaciones con la debida antelación, y en todo caso antes de que se le tome declaración.',c:'Derecho a actuar en el proceso penal para ejercer su derecho de defensa.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 118 LECrim establece que el derecho de defensa comprende el derecho a ser informado de los hechos, a examinar las actuaciones antes de declarar, y a actuar en el proceso.'}}
,{n:83,q:'Según el artículo 118 de la Ley de Enjuiciamiento Criminal, toda persona a quien se atribuya un hecho punible podrá ejercer el derecho de defensa, que comprende el...',o:{a:'Derecho a no declarar contra sí mismo.',b:'Derecho a no confesarse culpable.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 118 LECrim establece que el derecho de defensa también comprende el derecho a no declarar contra uno mismo y a no confesarse culpable.'}}
,{n:84,q:'Según el artículo 118 de la Ley de Enjuiciamiento Criminal, toda persona a quien se atribuya un hecho punible podrá ejercer el derecho de defensa, que comprende el...',o:{a:'Derecho a designar libremente abogado, salvo en caso de incomunicación.',b:'Derecho a solicitar asistencia jurídica gratuita, procedimiento para hacerlo y condiciones para obtenerla.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'d',why:{d:'El art. 118 LECrim también reconoce el derecho a designar libremente abogado (con la excepción de la incomunicación) y el derecho a solicitar asistencia jurídica gratuita. Ambas son correctas.'}}
,{n:85,q:'Según el artículo 118.3 de la Ley de Enjuiciamiento Criminal, y con respecto al ejercicio del derecho de defensa en el proceso penal, indique la afirmación correcta.',o:{a:'Para actuar en el proceso penal, las personas investigadas deberán ser representadas por abogado.',b:'Para actuar en el proceso penal, las personas investigadas deberán ser defendidas por procurador.',c:'Para actuar en el proceso penal, serán defendidas por abogado designado de oficio, las personas investigadas que no lo hubiesen nombrado por sí mismas o lo solicitaren, o cuando no tuvieren aptitud legal para hacerlo.',d:'Todas las respuestas anteriores son correctas.'},correct:'c',why:{c:'El art. 118.3 LECrim establece que para actuar en el proceso penal, serán defendidas por abogado designado de oficio las personas investigadas que no lo hubiesen nombrado o lo solicitaren, o cuando no tuvieren aptitud legal.'}}
,{n:86,q:'Según el artículo 118.3 de la Ley de Enjuiciamiento Criminal, y con respecto al ejercicio del derecho de defensa en el proceso penal, las personas investigadas deberán ser representadas por abogado, designándoseles de oficio, requerido, cuando...',o:{a:'Cuando no lo hubiesen nombrado por sí mismas y lo solicitaren.',b:'Se les nombrará de oficio si, requerido, no lo hubieren nombrado antes de que la causa llegue a estado en que necesite el consejo de aquéllos.',c:'Se les nombrará de oficio si, requerido, no los nombrara cuando haya de intentar algún recurso que hiciese indispensable su actuación.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 118.3 LECrim establece que se designará abogado de oficio cuando el investigado no lo nombre habiendo sido requerido, cuando la causa llegue a estado que necesite su consejo, y cuando haya de intentar algún recurso que requiera su actuación.'}}
,{n:87,q:'Según el artículo 118.3 de la Ley de Enjuiciamiento Criminal, para actuar en el proceso, las personas investigadas deberán ser representadas por procurador y defendidas por abogado, designándoseles de oficio si, requerido:',o:{a:'Cuando no los hubieren nombrado por sí mismos y los solicitaren.',b:'Se les nombrará de oficio si, requerido, no los nombrara cuando haya de intentar algún recurso que hiciese indispensable su actuación.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 118.3 LECrim establece que se designarán procurador y abogado de oficio cuando el investigado los solicite o cuando haya de intentar un recurso que requiera su actuación.'}}
,{n:88,q:'Según el artículo 118.3 de la Ley de Enjuiciamiento Criminal, si el investigado o encausado en un proceso penal no hubiese designado Procurador o Letrado...',o:{a:'Se le requerirá para que lo haga.',b:'Se les nombrará de oficio si, requerido, los nombrara, cuando la causa llegue a estado en que se necesite el consejo de aquéllos.',c:'Se les nombrará de oficio si, requerido, no los nombrara cuando haya de intentar algún recurso que hiciese indispensable su actuación.',d:'Todas las respuestas anteriores son correctas.'},correct:'a',why:{a:'El art. 118.3 LECrim establece que si el investigado no ha designado Procurador o Letrado, se le requerirá para que lo haga.'}}
,{n:89,q:'Según el artículo 118.3 de la Ley de Enjuiciamiento Criminal, el abogado estará presente en todas las declaraciones de su defendido, así como en las diligencias de reconocimiento, careos y reconstrucción de hechos, salvo en aquellos casos:',o:{a:'En que existan indicios objetivos de la participación del abogado en el hecho investigado.',b:'Que tengan por objeto el enjuiciamiento de sujetos pertenecientes a bandas armadas o elementos terroristas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 118.3 LECrim establece que el abogado no estará presente en las declaraciones de su defendido cuando existan indicios objetivos de su participación en el hecho investigado o cuando se trate de bandas armadas o terrorismo.'}}
,{n:90,q:'En el ejercicio del derecho de defensa, el letrado estará presente en todas las declaraciones de su defendido, así como en las diligencias de reconocimiento, careos y reconstrucción de hechos, salvo en aquellos casos:',o:{a:'En que el investigado o encausado prescinda de su servicio renunciando a ese derecho por tratarse de un delito leve o menos grave.',b:'En que existan indicios objetivos de la participación del abogado en la comisión de otra infracción penal junto con el investigado o encausado.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 118.3 LECrim también establece que el abogado no asistirá cuando el investigado renuncie por delito leve o menos grave, o cuando existan indicios de participación del abogado en otra infracción penal con el encausado.'}}
,{n:91,q:'Según el artículo 118.4 de la Ley de Enjuiciamiento Criminal,...',o:{a:'Las comunicaciones entre el investigado o encausado y su abogado tendrán carácter confidencial cuando así lo haya establecido el Juez o Tribunal que conozca la causa.',b:'Si las comunicaciones o conversaciones entre el investigado o encausado y su abogado hubiesen sido captadas o intervenidas durante la ejecución de alguna diligencia, el juez ordenará la eliminación de la grabación o la entrega al destinatario de la correspondencia detenida, dejando constancia en las actuaciones.',c:'No tendrán carácter confidencial las comunicaciones entre el investigado o encausado y su abogado, si se constata la existencia de indicios objetivos de la participación del abogado en cualquier hecho delictivo de similar naturaleza al que se refiera la causa, cometido en los últimos cinco años.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 118.4 LECrim establece: que el carácter confidencial depende de lo que establezca el juez, que las grabaciones ilícitas se eliminarán, y que no habrá confidencialidad cuando haya indicios de participación del abogado en el delito.'}}
,{n:92,q:'Según el artículo 118.5 de la Ley de Enjuiciamiento Criminal, la admisión de denuncia o querella, y cualquier actuación procesal de la que resulte la imputación de un delito contra persona o personas determinadas, serán puestas inmediatamente en conocimiento de...',o:{a:'Los presuntamente responsables.',b:'De los representantes legales de los presuntamente responsables.',c:'Del Ministerio Fiscal.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 118.5 LECrim establece que la admisión de denuncia o querella y las actuaciones que imputen un delito se pondrán inmediatamente en conocimiento de los presuntamente responsables, sus representantes legales y el MF.'}}
,{n:93,q:'Según el artículo 119 de la Ley de Enjuiciamiento Criminal, cuando haya de procederse a la imputación de un delito a una persona jurídica:',o:{a:'La citación se hará en el domicilio social de la misma, requiriendo a la entidad para que proceda a la designación de representante.',b:'Se requerirá de la entidad que proceda a la designación de abogado y procurador.',c:'La comparecencia se practicará con el representante especialmente designado por la persona jurídica imputada, acompañado de su abogado.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 119 LECrim establece todas estas previsiones para la imputación de personas jurídicas: citación en domicilio social, designación de abogado y procurador, y comparecencia con representante designado y abogado.'}}
,{n:94,q:'Según el artículo 121 de la Ley de Enjuiciamiento Criminal, los que tuvieran reconocido el derecho a la asistencia jurídica gratuita...',o:{a:'Podrán designar abogado y procurador de su elección, pero en este caso estarán obligados a abonar sus honorarios y derechos.',b:'Podrán designar abogado y procurador de su elección, y los honorarios de estos profesionales serán sufragados por el Estado en los términos previstos en el artículo 27 de la Ley de Asistencia Jurídica Gratuita.',c:'No podrán designar abogado ni procurador, recibiendo la asistencia del turno de oficio, en los términos previstos en el artículo 27 de la Ley de Asistencia Jurídica Gratuita.',d:'Ninguna de las anteriores respuestas es correcta.'},correct:'b',why:{b:'El art. 121 LECrim establece que quienes tengan reconocido el derecho a asistencia jurídica gratuita podrán designar abogado y procurador de su elección, siendo sufragados los honorarios por el Estado en los términos del art. 27 de la Ley de Asistencia Jurídica Gratuita.'}}
,{n:95,q:'El derecho a la traducción e interpretación establecido en el Capítulo II del Título V del Libro I de la Ley de Enjuiciamiento Criminal, podrá ser ejercido por:',o:{a:'Los imputados o acusados que no hablen o entiendan el castellano.',b:'Los imputados o acusados que no hablen o entiendan la lengua oficial en la que se desarrolle la actuación.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 123 LECrim establece que el derecho a traducción e interpretación podrá ejercerse por los imputados o acusados que no hablen o entiendan el castellano o la lengua oficial en que se desarrolle la actuación.'}}
,{n:96,q:'Según el artículo 123 de la Ley de Enjuiciamiento Criminal, los investigados o acusados que no hablen o entiendan el castellano, o la lengua oficial en la que se desarrolle la actuación, tendrán derecho a...',o:{a:'Servirse de un intérprete en las conversaciones que mantenga con su abogado y que tengan relación directa con su posterior interrogatorio.',b:'Servirse de un intérprete en las conversaciones que mantenga con su abogado y que tengan relación directa con su posterior toma de declaración.',c:'La traducción de las resoluciones que acuerden su ingreso en prisión.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 123 LECrim establece que los investigados que no hablen castellano tienen derecho a intérprete en conversaciones con su abogado sobre el interrogatorio o toma de declaración, y a la traducción de resoluciones que acuerden su ingreso en prisión.'}}
,{n:97,q:'Según el artículo 123 de la Ley de Enjuiciamiento Criminal, los investigados o acusados que no hablen o entiendan el castellano, o la lengua oficial en la que se desarrolle la actuación, tendrán derecho a...',o:{a:'Derecho a ser asistidos por un intérprete en cualquier comunicación que lleven a cabo con sus representantes legales, o testigos que tengan relación con la causa.',b:'Derecho a la traducción escrita del escrito de acusación.',c:'Derecho a la traducción escrita de la sentencia.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 123 LECrim también establece el derecho a intérprete en comunicaciones con representantes legales o testigos relacionados con la causa, y a la traducción escrita del escrito de acusación y de la sentencia.'}}
,{n:98,q:'Según el artículo 123 de la Ley de Enjuiciamiento Criminal, los investigados o acusados que no hablen o entiendan el castellano, o la lengua oficial en la que se desarrolle la actuación, tendrán derecho a...',o:{a:'Derecho a ser asistidos por un intérprete durante todas las actuaciones, incluyendo el interrogatorio policial o por el Ministerio Fiscal y todas las vistas judiciales.',b:'Derecho a servirse de intérprete en las conversaciones que mantenga con su abogado y que resulten necesarias para la presentación de un recurso o para otras solicitudes procesales.',c:'Derecho a la interpretación de todas las actuaciones del juicio oral.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 123 LECrim también establece el derecho a intérprete durante el interrogatorio policial y vistas judiciales, en conversaciones con el abogado para recursos o solicitudes procesales, y en la interpretación del juicio oral.'}}
,{n:99,q:'Según el artículo 123 de la Ley de Enjuiciamiento Criminal, los investigados o acusados que no hablen o entiendan el castellano, o la lengua oficial en la que se desarrolle la actuación, tendrán derecho a...',o:{a:'Derecho a ser asistidos por un intérprete durante el interrogatorio policial o por el Ministerio Fiscal y todas las vistas judiciales.',b:'Derecho a servirse de intérprete en las conversaciones que mantenga con su abogado y que resulten necesarias para la presentación de un recurso.',c:'Derecho a la traducción escrita de los documentos que resulten esenciales para garantizar el ejercicio de su derecho de defensa.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 123 LECrim reconoce también el derecho a intérprete en el interrogatorio policial y vistas, en conversaciones con el abogado para recursos, y a la traducción escrita de documentos esenciales.'}}
,{n:100,q:'Según el artículo 123 de la Ley de Enjuiciamiento Criminal, los investigados o acusados que no hablen o entiendan el castellano, o la lengua oficial en la que se desarrolle la actuación, tendrán derecho a...',o:{a:'Derecho a la traducción escrita de los documentos que resulten esenciales para garantizar el ejercicio de su derecho de defensa.',b:'Derecho a presentar una solicitud motivada para que se considere esencial un documento.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 123 LECrim establece que los investigados tienen derecho a la traducción escrita de documentos esenciales y a presentar solicitud motivada para que se considere esencial un documento.'}}
,{n:101,q:'Según el artículo 123 de la Ley de Enjuiciamiento Criminal, los investigados o acusados que no hablen o entiendan el castellano, o la lengua oficial en la que se desarrolle la actuación, tendrán derecho a...',o:{a:'Derecho a la traducción escrita de las resoluciones firmes de cualesquiera otros tribunales, que deban incorporarse a la causa.',b:'Derecho a la traducción escrita de las resoluciones que acuerden el sobreseimiento de la causa.',c:'Presentar una solicitud de fianza en caso de acusación y denuncia falsa.',d:'Todas las respuestas anteriores son correctas.'},correct:'b',why:{b:'El art. 123 LECrim establece el derecho a la traducción escrita de las resoluciones que acuerden el sobreseimiento de la causa, entre otras resoluciones esenciales.'}}
,{n:102,q:'Con respecto a los derechos de traducción e interpretación establecidos en el Capítulo II del Título V del Libro I de la Ley de Enjuiciamiento Criminal, indique la afirmación incorrecta:',o:{a:'La renuncia a estos derechos deberá ser expresa y libre.',b:'Los gastos de traducción e interpretación derivados del ejercicio de estos derechos serán sufragados por la Administración, siempre que el afectado acredite que no puede hacerlo por sí mismo.',c:'La renuncia a estos derechos solo será válida si el investigado o acusado ha recibido antes un asesoramiento jurídico suficiente que le permita tener conocimiento de las consecuencias de su renuncia.',d:'Los derechos contenidos en las letras a) y c) del artículo 123 de la Ley de Enjuiciamiento Criminal son irrenunciables.'},correct:'b',why:{b:'El art. 123 LECrim establece que los gastos de traducción e interpretación serán sufragados por la Administración con independencia del resultado del proceso. La condición de acreditar que no puede hacerlos por sí mismo es incorrecta.'}}
,{n:103,q:'Según el artículo 123 de la Ley de Enjuiciamiento Criminal, los gastos de traducción e interpretación derivados del ejercicio de estos derechos serán sufragados:',o:{a:'Por la Administración, con independencia del resultado del proceso.',b:'Por la Administración, cuando el resultado del proceso sea favorable al investigado o acusado, y por éste en los demás casos.',c:'Por el investigado o acusado, en todos los casos.',d:'Por la Administración siempre que el afectado demuestre que no puede hacerlo por sí mismo.'},correct:'a',why:{a:'El art. 123 LECrim establece que los gastos de traducción e interpretación serán sufragados por la Administración, con independencia del resultado del proceso.'}}
,{n:104,q:'Todas las autoridades y funcionarios que intervengan en el procedimiento penal, dentro de los límites de su respectiva competencia:',o:{a:'Cuidarán de consignar y apreciar las circunstancias, tanto adversas como favorables al presunto reo.',b:'Estarán obligados, a falta de disposición expresa, a instruir al presunto reo de sus derechos y de los recursos que pueda ejercitar, mientras no se hallare asistido de defensor.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 104 LECrim establece que todas las autoridades y funcionarios del procedimiento penal deben consignar circunstancias adversas y favorables al presunto reo, e instruirle de sus derechos y recursos si no está asistido de defensor.'}}
,{n:105,q:'El procedimiento de "Habeas Corpus" se encuentra regulado:',o:{a:'En la Ley Orgánica 6/1985, de 1 de julio.',b:'En la Ley Orgánica 6/1984, de 24 de mayo.',c:'En la Ley Orgánica 10/1995, de 23 de noviembre.',d:'En la Ley Orgánica 2/1986, de 13 de junio.'},correct:'b',why:{b:'El procedimiento de Habeas Corpus se encuentra regulado en la Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de "Habeas Corpus".'}}
,{n:106,q:'La Ley Orgánica 6/1984, reguladora del procedimiento de "Habeas Corpus" fue declarada expresamente vigente:',o:{a:'Por la disposición final de la Ley Orgánica 10/1995, del Código Penal.',b:'Por el número 2 de la disposición derogatoria de la Ley Orgánica del Poder Judicial.',c:'Por la disposición final de la Ley Orgánica del Poder Judicial.',d:'Por el número 1 de la disposición derogatoria de la Ley Orgánica del Poder Judicial.'},correct:'b',why:{b:'La LO 6/1984, reguladora del procedimiento de Habeas Corpus, fue declarada expresamente vigente por el número 2 de la disposición derogatoria de la Ley Orgánica del Poder Judicial.'}}
,{n:107,q:'Mediante el procedimiento de "Habeas Corpus":',o:{a:'Se puede obtener la inmediata puesta a disposición de la autoridad judicial competente de cualquier persona detenida ilegalmente.',b:'Se puede obtener la inmediata puesta en libertad de cualquier persona detenida ilegalmente, sin necesidad de que haya sido puesta a disposición de la autoridad judicial.',c:'Se puede obtener la inmediata puesta en libertad de cualquier persona detenida, con independencia de si la detención se ha producido legal o ilegalmente.',d:'Se puede obtener la inmediata puesta en libertad de cualquier persona ilegalmente detenida, siempre que lo acuerde la autoridad judicial competente, mediante sentencia motivada.'},correct:'a',why:{a:'El procedimiento de Habeas Corpus permite obtener la inmediata puesta a disposición de la autoridad judicial competente de cualquier persona detenida ilegalmente.'}}
,{n:108,q:'De acuerdo con lo establecido en la Ley Orgánica 6/1984, reguladora del procedimiento de "Habeas Corpus", se consideran personas ilegalmente detenidas:',o:{a:'Las que estén ilícitamente internadas en cualquier establecimiento o lugar.',b:'Las que lo estuvieren por plazo superior al señalado en las leyes si, transcurrido el mismo, no fuesen puestas en libertad o entregadas al Juez más próximo al lugar de la detención.',c:'Las privadas de libertad a quienes no les sean respetados los derechos que la Constitución y las Leyes Procesales garantizan a toda persona detenida.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'La LO 6/1984 establece que se consideran ilegalmente detenidas las internadas ilícitamente, las detenidas más del plazo legal sin ser puestas en libertad o entregadas al juez, y las que no ven respetados sus derechos constitucionales.'}}
,{n:109,q:'A efectos de la Ley Orgánica 6/1984, reguladora del procedimiento de "Habeas Corpus", se consideran personas ilegalmente detenidas:',o:{a:'Las que fueren detenidas por una autoridad, agente de la misma, funcionario público o particular, sin que concurran los supuestos legales.',b:'Las que fueran detenidas por una autoridad, agente de la misma, funcionario público o particular, sin haberse cumplido las formalidades prevenidas y requisitos exigidos por las Leyes.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'La LO 6/1984 también considera ilegalmente detenidas a las personas detenidas sin que concurran los supuestos legales y a las que lo hayan sido sin cumplirse las formalidades exigidas por las leyes.'}}
,{n:110,q:'De acuerdo con lo establecido en el artículo 3 de la Ley Orgánica 6/1984, podrá instar el procedimiento de "Habeas Corpus":',o:{a:'El privado de libertad, su cónyuge o persona unida por análoga relación de afectividad, ascendientes, descendientes, hermanos y, en su caso, respecto a los menores e incapacitados, sus representantes legales.',b:'El Ministerio Fiscal.',c:'El Defensor del Pueblo.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 3 LO 6/1984 establece que podrán instar el Habeas Corpus el privado de libertad y sus familiares, el Ministerio Fiscal y el Defensor del Pueblo.'}}
,{n:111,q:'De acuerdo con lo establecido en el artículo 3 de la Ley Orgánica 6/1984, podrá instar de oficio el procedimiento de "Habeas Corpus":',o:{a:'El Ministerio Fiscal.',b:'El Defensor del Pueblo.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'a',why:{a:'El art. 3 LO 6/1984 establece que podrá instar de oficio el procedimiento de Habeas Corpus el Ministerio Fiscal.'}}
,{n:112,q:'Es competente para conocer de la solicitud de "Habeas Corpus":',o:{a:'El Juez de Primera Instancia del lugar en el que se encuentre la persona privada de libertad.',b:'El Juez de Instrucción del lugar en el que se encuentre la persona privada de libertad.',c:'El Juez de lo Penal del lugar en el que se encuentre la persona privada de libertad.',d:'El Juez de lo Contencioso Administrativo del lugar en el que se encuentre la persona privada de libertad.'},correct:'b',why:{b:'La LO 6/1984 establece que es competente para conocer de la solicitud de Habeas Corpus el Juez de Instrucción del lugar en el que se encuentre la persona privada de libertad.'}}
,{n:113,q:'Cuando no conste el lugar donde se encuentra la persona privada de libertad, el juez competente para conocer de la solicitud de Habeas Corpus es:',o:{a:'El Juez de Instrucción del lugar en que se produzca la detención y, en su defecto, el del lugar en el que se hayan tenido las últimas noticias del paradero del detenido.',b:'El Juez de Instrucción del lugar donde se produzca la detención y, en su defecto el de la Audiencia Nacional.',c:'El Juez de Instrucción del lugar donde se hubiesen tenido las últimas noticias del privado de libertad, y en su defecto el de la Audiencia Provincial.',d:'El Juez de Instrucción del lugar donde se produzca la detención, y en su defecto el Defensor del Pueblo.'},correct:'a',why:{a:'La LO 6/1984 establece que cuando no conste el lugar de privación de libertad, será competente el Juez de Instrucción del lugar en que se produzca la detención y, en su defecto, el del lugar en que se hayan tenido las últimas noticias del paradero.'}}
,{n:114,q:'En el ámbito de la Jurisdicción Militar, será competente para conocer de la solicitud de "Habeas Corpus":',o:{a:'El Defensor del Pueblo.',b:'El Juez Togado Militar de Instrucción constituido en la cabecera de la circunscripción en la que se efectuó la detención.',c:'El Juez de Instrucción del lugar en que se encuentre el detenido.',d:'El Jefe del Estado Mayor de la Defensa.'},correct:'b',why:{b:'La LO 6/1984 establece que en el ámbito de la Jurisdicción Militar, será competente el Juez Togado Militar de Instrucción constituido en la cabecera de la circunscripción en la que se efectuó la detención.'}}
,{n:115,q:'En los delitos de terrorismo, será competente para conocer de la solicitud de "Habeas Corpus":',o:{a:'El Juez Central de Instrucción correspondiente.',b:'El Tribunal Supremo.',c:'La Sala correspondiente de la Audiencia Nacional.',d:'El Juzgado Central de lo Penal que corresponda.'},correct:'a',why:{a:'En los delitos de terrorismo, será competente para conocer de la solicitud de Habeas Corpus el Juez Central de Instrucción correspondiente.'}}
,{n:116,q:'El procedimiento de "Habeas Corpus" se iniciará por medio de escrito o comparecencia, salvo cuando se incoe de oficio, siendo preceptiva la intervención de:',o:{a:'Abogado.',b:'Procurador.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'d',why:{d:'El procedimiento de Habeas Corpus no requiere la preceptiva intervención de abogado ni de procurador. Ninguna de las opciones a y b es correcta.'}}
,{n:117,q:'En el escrito en el que se solicita el "Habeas Corpus" debe constar:',o:{a:'El nombre y circunstancias personales del solicitante y de la persona para la que se solicita el procedimiento.',b:'El lugar donde se halla privada de libertad la persona para la que se solicita el procedimiento.',c:'La autoridad bajo cuya custodia se encuentre la persona privada de libertad y el motivo concreto por el que se solicita el Habeas Corpus.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'La LO 6/1984 establece que el escrito de Habeas Corpus debe contener los datos personales del solicitante y el detenido, el lugar de detención, la autoridad bajo cuya custodia se encuentre, y el motivo concreto de la solicitud.'}}
,{n:118,q:'De acuerdo con lo establecido en el artículo 5 de la Ley Orgánica 6/1984, están obligados a poner inmediatamente en conocimiento del Juez competente la solicitud de "Habeas Corpus":',o:{a:'La autoridad gubernativa.',b:'Los agentes de la autoridad gubernativa.',c:'Los funcionarios públicos.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 5 LO 6/1984 establece que están obligados a poner en conocimiento del Juez la solicitud de Habeas Corpus la autoridad gubernativa, sus agentes, y los funcionarios públicos.'}}
,{n:119,q:'Promovida una solicitud de "Habeas Corpus", el Juez competente:',o:{a:'Examinará la concurrencia de los requisitos para su tramitación.',b:'Decretará la libertad del detenido.',c:'Determinará que el detenido sea atendido por un facultativo.',d:'Nombrará defensor al privado de libertad, si este no lo tuviere, y le oirá en el plazo máximo de 8 horas.'},correct:'a',why:{a:'Promovida una solicitud de Habeas Corpus, el Juez competente examinará la concurrencia de los requisitos para su tramitación.'}}
,{n:120,q:'Promovida una solicitud de "Habeas Corpus", el Juez competente:',o:{a:'Resolverá en el plazo máximo de 12 horas.',b:'Dará traslado de la misma al Ministerio Fiscal.',c:'Decretará la libertad del detenido.',d:'Solicitará la información que considere necesaria al funcionario de la Policía Judicial que haya practicado la detención.'},correct:'b',why:{b:'Promovida una solicitud de Habeas Corpus, el Juez competente dará traslado de la misma al Ministerio Fiscal.'}}
,{n:121,q:'Promovida una solicitud de "Habeas Corpus", el Juez competente:',o:{a:'Examinará la concurrencia de los requisitos para su tramitación.',b:'Dará traslado de la misma al Ministerio Fiscal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'Promovida una solicitud de Habeas Corpus, el Juez competente examinará la concurrencia de los requisitos para su tramitación y dará traslado de la misma al Ministerio Fiscal.'}}
,{n:122,q:'Promovida una solicitud de "Habeas Corpus", el Juez competente examinará la concurrencia de los requisitos para su tramitación, acordará la incoación del procedimiento, o, en su caso, denegará la solicitud por ser ésta improcedente, mediante:',o:{a:'Auto.',b:'Providencia.',c:'Decreto.',d:'Sentencia.'},correct:'a',why:{a:'La LO 6/1984 establece que el Juez, tras examinar la solicitud de Habeas Corpus, acordará la incoación del procedimiento o denegará la solicitud mediante auto.'}}
,{n:123,q:'En el auto de incoación de un procedimiento de "Habeas Corpus", el Juez ordenará a la autoridad a cuya disposición se halle la persona privada de libertad o a aquél en cuyo poder se encuentre, que la ponga de manifiesto ante él:',o:{a:'En el plazo más breve posible, sin exceder en ningún caso de 3 horas.',b:'Sin pretexto ni demora alguna.',c:'En el plazo máximo de 8 horas.',d:'Inmediatamente.'},correct:'a',why:{a:'La LO 6/1984 establece que en el auto de incoación el Juez ordenará que se ponga de manifiesto al detenido en el plazo más breve posible, sin exceder en ningún caso de 3 horas.'}}
,{n:124,q:'En el auto de incoación de un procedimiento de "Habeas Corpus", el Juez ordenará a la autoridad a cuya disposición se halle la persona privada de libertad o a aquél en cuyo poder se encuentre, que la ponga de manifiesto ante él sin pretexto ni demora alguna.',o:{a:'O se constituirá en el lugar donde aquélla se encuentre.',b:'O decretará su inmediata puesta en libertad.',c:'O sancionará disciplinariamente a los funcionarios encargados de su custodia.',d:'Todas las respuestas anteriores son correctas.'},correct:'a',why:{a:'La LO 6/1984 establece que el Juez ordenará la puesta de manifiesto del detenido ante él o se constituirá en el lugar donde aquélla se encuentre.'}}
,{n:125,q:'El Juez competente en un procedimiento de "Habeas Corpus", antes de dictar resolución oirá a la persona privada de libertad, al Ministerio Fiscal, a quien hubiera practicado la detención y a la persona bajo cuya custodia se encontrase:',o:{a:'En el plazo de 72 horas, contadas desde que se ha dictado el auto de incoación.',b:'En el plazo de 24 horas, contadas desde que se ha dictado el auto de incoación.',c:'En el plazo de 48 horas, contadas desde que se ha dictado el auto de incoación.',d:'En el plazo de 12 horas, contadas desde que se ha dictado el auto de incoación.'},correct:'d',why:{d:'La LO 6/1984 establece que el Juez oirá a las partes en el plazo de 12 horas contadas desde que se ha dictado el auto de incoación del procedimiento de Habeas Corpus.'}}
,{n:126,q:'El Juez competente en un procedimiento de "Habeas Corpus" dará a conocer las declaraciones del privado de libertad:',o:{a:'A la autoridad, agentes, funcionario público o representante de la institución o persona que hubiere ordenado o practicado el internamiento.',b:'A aquélla persona bajo cuya custodia se encontrase la persona privada de libertad.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'La LO 6/1984 establece que el Juez dará a conocer las declaraciones del privado de libertad tanto a quien hubiere ordenado o practicado el internamiento como a quien tenga bajo su custodia al privado de libertad.'}}
,{n:127,q:'El juez competente en un procedimiento de "Habeas Corpus", tras practicar todas las actuaciones preceptivas, si estima que se concurre alguna de las circunstancias del art.1 de la Ley Orgánica 6/1984, mediante auto motivado, acordará en el acto:',o:{a:'El archivo de las actuaciones, declarando ser conforme a derecho la privación de libertad y las circunstancias en las que se ha realizado.',b:'La puesta en libertad del privado de ésta, si lo fue ilegalmente.',c:'Que la persona privada de libertad sea puesta inmediatamente a disposición judicial, si ya hubiere transcurrido el plazo legalmente establecido para su detención.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'La LO 6/1984 establece que si el juez aprecia ilegalidad, mediante auto motivado acordará el archivo si la detención fue conforme a derecho, la puesta en libertad si fue ilegal, y la puesta a disposición judicial si se han superado los plazos.'}}
,{n:128,q:'El juez competente en un procedimiento de "Habeas Corpus", tras practicar todas las actuaciones preceptivas, si estima que concurre alguna de las circunstancias del art.1 de la Ley Orgánica 6/1984, mediante auto motivado, acordará en el acto:',o:{a:'La puesta en libertad del privado de ésta, si lo fue ilegalmente.',b:'La situación de privación de libertad, de acuerdo con las disposiciones legales aplicables al caso.',c:'Que la persona privada de libertad sea puesta inmediatamente a disposición judicial, si ya hubiere transcurrido el plazo legalmente establecido para su detención.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'La LO 6/1984 establece que el auto motivado del juez podrá acordar la puesta en libertad si fue ilegal, la adecuación de la situación a las disposiciones legales, o la puesta a disposición judicial si se han superado los plazos.'}}
];
